// Generated by esquadro: do not edit. The dashboard: the reports marked as
// widgets, each a number, a chart or a table, for a period (today, the last
// 7 or 30 days, all time) that fills their time parameter.
import { useQuery } from "@tanstack/react-query"
import * as icons from "lucide-react"
import type { LucideIcon } from "lucide-react"
import { AlertTriangle, RotateCw } from "lucide-react"
import { useState } from "react"
import { Bar, BarChart, CartesianGrid, Line, LineChart as Lines, XAxis, YAxis } from "recharts"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { ChartContainer, ChartTooltip, ChartTooltipContent } from "@/components/ui/chart"
import type { ChartConfig } from "@/components/ui/chart"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Skeleton } from "@/components/ui/skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { cn } from "@/lib/utils"
import { api } from "../api.ts"
import { locale } from "../config.ts"
import { widgets as declared } from "../dashboard.gen.ts"
import { describe } from "./errors.ts"
import { capitalize, format, t } from "./i18n.ts"
import type { FieldMeta } from "./meta.ts"
import { currencyOf, formatMoney, formatTotals, isMoney, sumMoney } from "./money.tsx"
import type { Money } from "./money.tsx"
import { PageHeader } from "./page.tsx"

type Row = Record<string, unknown>

/** A report on the dashboard, as the model marks it. */
export interface Widget {
  name: string
  label: string
  kind: "stat" | "bar" | "line" | "table"
  x?: string
  y?: string
  since?: string
  columns: FieldMeta[]
  /** A Lucide icon for a number: shopping_cart. */
  icon?: string
  fetch: (api: never, params: Record<string, unknown>) => Promise<Row[]>
}

const DAY = 86_400_000

/** The periods, each its start (none: all time). */
function periods(): { key: string; label: string; since?: Date }[] {
  const now = new Date()
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  return [
    { key: "today", label: t("today"), since: today },
    { key: "7d", label: t("last7days"), since: new Date(today.getTime() - 6 * DAY) },
    { key: "30d", label: t("last30days"), since: new Date(today.getTime() - 29 * DAY) },
    { key: "all", label: t("allTime") },
  ]
}

/**
 * The dashboard of the widgets: yours to place on a page (the first one),
 * under a title of yours, with the period at its right.
 */
export function Dashboard({
  widgets = declared,
  title,
  description,
}: {
  widgets?: Widget[]
  title?: string
  description?: string
}) {
  const [period, setPeriod] = useState("30d")
  const [picked, setPicked] = useState<string>()
  const since = periods().find((p) => p.key === period)?.since
  const timed = widgets.some((w) => w.since)
  const stats = widgets.filter((w) => w.kind === "stat")
  const others = widgets.filter((w) => w.kind !== "stat")
  // A number over a column (its x: a day) is drawn under the numbers, the
  // one picked; a number without one is only its total.
  const drawn = stats.filter((w) => w.x)
  const shown = drawn.find((w) => w.name === picked) ?? drawn[0]
  const picker = timed && (
    <div className="flex items-center gap-2">
      <span className="text-sm font-semibold text-muted-foreground">{t("period")}:</span>
      <Select value={period} onValueChange={setPeriod}>
        <SelectTrigger className="h-10 w-44 bg-card shadow-xs" aria-label={t("period")}>
          <SelectValue />
        </SelectTrigger>
        <SelectContent align="end">
          {periods().map((p) => (
            <SelectItem key={p.key} value={p.key}>
              {p.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  )
  return (
    <div className="flex flex-col gap-4">
      {(title || picker) && <PageHeader title={title ?? ""} description={description} actions={picker || undefined} />}
      {stats.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>{t("overview")}</CardTitle>
          </CardHeader>
          <CardContent>
            {/* The numbers, side by side in a tray, as many as fit. */}
            <div className="grid grid-cols-[repeat(auto-fill,minmax(240px,1fr))] gap-3 rounded-2xl bg-muted p-3">
              {stats.map((w, i) => (
                <StatTile
                  key={w.name}
                  widget={w}
                  since={since}
                  tone={i}
                  active={drawn.length > 1 ? w === shown : undefined}
                  onPick={drawn.length > 1 && w.x ? () => setPicked(w.name) : undefined}
                />
              ))}
            </div>
            {shown && <StatChart widget={shown} since={since} />}
          </CardContent>
        </Card>
      )}
      {others.length > 0 && (
        <div className="grid gap-4 lg:grid-cols-2">
          {others.map((w) => (
            <WidgetCard key={w.name} widget={w} since={since} />
          ))}
        </div>
      )}
    </div>
  )
}

/** The colors of the numbers' icons, in turn. */
const TONES = [
  "bg-sky-200 text-neutral-900 dark:bg-sky-500/25 dark:text-sky-200",
  "bg-emerald-200 text-neutral-900 dark:bg-emerald-500/25 dark:text-emerald-200",
  "bg-violet-200 text-neutral-900 dark:bg-violet-500/25 dark:text-violet-200",
  "bg-orange-200 text-neutral-900 dark:bg-orange-500/25 dark:text-orange-200",
]

function iconOf(name?: string): LucideIcon {
  const key = (name ?? "")
    .split(/[-_ ]/)
    .filter(Boolean)
    .map((p) => p[0].toUpperCase() + p.slice(1))
    .join("")
  return ((icons as unknown as Record<string, LucideIcon>)[key] ?? icons.ChartColumn) as LucideIcon
}

function useRows(w: Widget, since?: Date) {
  const params: Record<string, unknown> = {}
  if (w.since && since) params[w.since] = since.toISOString()
  return useQuery({
    queryKey: ["reports", w.name, params],
    queryFn: () => w.fetch(api as never, params),
  })
}

/**
 * A number: its name, its icon in a colored circle, the number. Among
 * numbers drawn over time, the one drawn is raised, and a click draws
 * another.
 */
function StatTile({
  widget: w,
  since,
  tone,
  active,
  onPick,
}: {
  widget: Widget
  since?: Date
  tone: number
  active?: boolean
  onPick?: () => void
}) {
  const rows = useRows(w, since)
  const yCol = w.columns.find((c) => c.name === w.y)
  const Icon = iconOf(w.icon)
  const Tile = onPick ? "button" : "div"
  return (
    <Tile
      {...(onPick && { type: "button" as const, onClick: onPick, "aria-pressed": active })}
      className={cn(
        "flex min-w-0 flex-col gap-3 rounded-2xl p-4 text-left transition-[background-color,box-shadow] duration-150",
        active === false ? "hover:bg-card/60" : "bg-card shadow-xs",
        active && "shadow-md",
        onPick && "cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring",
      )}
    >
      {/* Its name and icon on a line, the number under them, the whole width. */}
      <div className="flex items-start justify-between gap-3">
        <p className="min-w-0 truncate pt-1 text-sm font-semibold text-muted-foreground">{w.label}</p>
        <div className={cn("flex size-12 shrink-0 items-center justify-center rounded-full", TONES[tone % TONES.length])}>
          <Icon className="size-5" />
        </div>
      </div>
      <div className="text-2xl font-bold tracking-tight text-foreground tabular-nums [overflow-wrap:anywhere] xl:text-3xl">
          {rows.isPending ? (
            <Skeleton className="h-9 w-24" />
          ) : rows.isError ? (
            <span
              role="button"
              tabIndex={0}
              className="text-base text-destructive underline-offset-4 hover:underline"
              title={describe(rows.error)}
              onClick={(e) => {
                e.stopPropagation()
                rows.refetch()
              }}
            >
              {t("retry")}
            </span>
          ) : (
            yCol?.kind === "money" ? (
              formatTotals(sumMoney(rows.data.map((r) => r[w.y ?? ""])))
            ) : (
              format(yCol ?? ({ kind: "decimal" } as FieldMeta), total(rows.data, w.y))
            )
          )}
      </div>
    </Tile>
  )
}

/** The number picked, drawn over its x: the same rows as its total. */
function StatChart({ widget: w, since }: { widget: Widget; since?: Date }) {
  const rows = useRows(w, since)
  const x = w.columns.find((c) => c.name === w.x)
  const y = w.columns.find((c) => c.name === w.y)
  if (rows.isPending) return <Skeleton className="mt-6 h-64 w-full" />
  if (!rows.data || rows.data.length === 0) return <p className="py-10 text-center text-sm text-muted-foreground">{rows.isError ? describe(rows.error) : t("noData")}</p>
  return (
    <div className="mt-6">
      <LineChart rows={named(rows.data, x)} x={w.x!} y={w.y!} label={y?.label} money={moneyOf(rows.data, y)} />
    </div>
  )
}

/** A chart or a table, in a card of its own. */
function WidgetCard({ widget: w, since }: { widget: Widget; since?: Date }) {
  const rows = useRows(w, since)
  const column = (name?: string) => w.columns.find((c) => c.name === name)
  const yCol = column(w.y)
  return (
    <Card>
      <CardHeader>
        <CardTitle>{w.label}</CardTitle>
      </CardHeader>
      <CardContent>
        {rows.isPending && <Skeleton className={w.kind === "table" ? "h-40 w-full" : "h-64 w-full"} />}
        {rows.isError && (
          <div className="flex flex-col items-center gap-2 py-6 text-center text-sm text-destructive" role="alert">
            <AlertTriangle className="size-5" />
            <span>{describe(rows.error)}</span>
            <Button variant="outline" size="sm" onClick={() => rows.refetch()}>
              <RotateCw /> {t("retry")}
            </Button>
          </div>
        )}
        {rows.data && rows.data.length === 0 && <p className="py-10 text-center text-sm text-muted-foreground">{t("noData")}</p>}
        {rows.data && rows.data.length > 0 && w.kind === "bar" && <BarsChart rows={named(rows.data, column(w.x))} x={w.x!} y={w.y!} label={yCol?.label} money={moneyOf(rows.data, yCol)} />}
        {rows.data && rows.data.length > 0 && w.kind === "line" && <LineChart rows={named(rows.data, column(w.x))} x={w.x!} y={w.y!} label={yCol?.label} money={moneyOf(rows.data, yCol)} />}
        {rows.data && rows.data.length > 0 && w.kind === "table" && <ReportTable rows={rows.data} columns={w.columns} />}
      </CardContent>
    </Card>
  )
}

/** The rows with their names (x) as people read them: an enum's labels. */
function named(rows: Row[], x?: FieldMeta): Row[] {
  if (!x || x.kind !== "enum") return rows
  return rows.map((r) => ({ ...r, [x.name]: format(x, r[x.name]) }))
}

/** The y column, summed over the rows. */
export function total(rows: Row[] | undefined, y?: string): number {
  return (rows ?? []).reduce((sum, r) => sum + (Number(r[y ?? ""]) || 0), 0)
}

/** The currency a money column's rows are in, for its chart. */
function moneyOf(rows: Row[], y?: FieldMeta): string | undefined {
  if (y?.kind !== "money") return undefined
  const first = rows.find((r) => isMoney(r[y.name]))
  return first ? currencyOf(first[y.name] as Money) : undefined
}

/** A chart's scale, short: 1,4 mil, or R$ 1,4 mil for money. */
function tickOf(money?: string) {
  const scale = new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1, ...(money && { style: "currency", currency: money }) })
  return (v: number) => scale.format(v)
}

/** A chart's tooltip: a money value with its currency. */
function tooltipOf(money?: string, label?: string) {
  if (!money) return <ChartTooltipContent />
  return (
    <ChartTooltipContent
      formatter={(value, name) => (
        <div className="flex w-full items-center justify-between gap-4">
          <span className="text-muted-foreground">{label ?? name}</span>
          <span className="font-semibold text-foreground tabular-nums">{formatMoney({ amount: String(value), currency: money })}</span>
        </div>
      )}
    />
  )
}

/**
 * The rows as a chart draws them: the names as read, the numbers as numbers
 * (an amount's text drawn as a number: the chart only places it; what is
 * read, the tooltip, is exact).
 */
function chartRows(rows: Row[], x: string, y: string) {
  return rows.map((r) => {
    const v = r[y]
    return { ...r, [x]: capitalize(String(r[x] ?? "—")), [y]: Number(isMoney(v) ? v.amount : v) || 0 }
  })
}

/** Bars of a report's rows: x, the name of each; y, the number. */
export function BarsChart({ rows, x, y, label, money }: { rows: Row[]; x: string; y: string; label?: string; money?: string }) {
  const config = { [y]: { label: label ?? y, color: "var(--chart-1)" } } satisfies ChartConfig
  return (
    <ChartContainer config={config} className="aspect-auto h-64 w-full">
      <BarChart data={chartRows(rows, x, y)} accessibilityLayer margin={ { left: 0 } }>
        <CartesianGrid vertical={false} />
        <XAxis dataKey={x} tickLine={false} axisLine={false} tickMargin={10} />
        <YAxis tickLine={false} axisLine={false} tickMargin={8} width={money ? 72 : 56} tickFormatter={tickOf(money)} />
        <ChartTooltip cursor={false} content={tooltipOf(money, label)} />
        <Bar dataKey={y} fill={`var(--color-${y})`} radius={[8, 8, 0, 0]} maxBarSize={48} />
      </BarChart>
    </ChartContainer>
  )
}

/** A smooth line over a report's rows, in their order: days, months. */
export function LineChart({ rows, x, y, label, money }: { rows: Row[]; x: string; y: string; label?: string; money?: string }) {
  const config = { [y]: { label: label ?? y, color: "var(--chart-1)" } } satisfies ChartConfig
  return (
    <ChartContainer config={config} className="aspect-auto h-64 w-full">
      <Lines data={chartRows(rows, x, y)} accessibilityLayer margin={ { left: 0, right: 8 } }>
        <CartesianGrid vertical={false} />
        <XAxis dataKey={x} tickLine={false} axisLine={false} tickMargin={10} />
        <YAxis tickLine={false} axisLine={false} tickMargin={8} width={money ? 72 : 56} tickFormatter={tickOf(money)} />
        <ChartTooltip content={tooltipOf(money, label)} />
        <Line dataKey={y} type="monotone" stroke={`var(--color-${y})`} strokeWidth={3} dot={false} activeDot={ { r: 5 } } />
      </Lines>
    </ChartContainer>
  )
}

/** A report's rows as a table, each column as people read it. */
export function ReportTable({ rows, columns }: { rows: Row[]; columns: FieldMeta[] }) {
  return (
    <div className="max-h-72 overflow-auto">
      <Table>
        <TableHeader>
          <TableRow>
            {columns.map((c) => (
              <TableHead key={c.name}>{c.label}</TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((r, i) => (
            <TableRow key={i}>
              {columns.map((c) => (
                <TableCell key={c.name}>{r[c.name] === null || r[c.name] === undefined ? "—" : format(c, r[c.name])}</TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}
